using System.ComponentModel;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ── In-memory note store ────────────────────────────────────────────────
var notes = new List<string>();

// ── Define tools ────────────────────────────────────────────────────────
var searchTool = AIFunctionFactory.Create(SearchWeb, "search_web",
    "Search the web for information. Returns relevant snippets.");

var saveNoteTool = AIFunctionFactory.Create(SaveNote, "save_note",
    "Save a research note for later reference.");

var getNotesTool = AIFunctionFactory.Create(GetNotes, "get_notes",
    "Retrieve all saved research notes.");

// ── Configure AI client with automatic tool invocation ──────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

IChatClient innerClient = new OpenAIClient(apiKey)
    .GetChatClient("gpt-4o-mini")
    .AsIChatClient();

// UseFunctionInvocation handles the tool-call ↔ result loop automatically
IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

// ── Get topic from user ─────────────────────────────────────────────────
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// ── Run the agent ───────────────────────────────────────────────────────
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Given a topic you must:
        1. Search the web with several varied queries to gather broad information.
        2. Save the most important findings as notes using the save_note tool.
        3. After gathering enough data, review your notes with get_notes.
        4. Produce a comprehensive, well-structured summary of your research.
        Be thorough — use at least 3 different search queries.
        """),
    new(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary:\n\n{topic}")
};

var response = await agent.GetResponseAsync(messages, new ChatOptions
{
    Tools = [searchTool, saveNoteTool, getNotesTool],
    Temperature = 0.2f
});

// ── Print results ───────────────────────────────────────────────────────
Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine($"\n═══════════════════════════════════════════");
    Console.WriteLine($"  COLLECTED NOTES ({notes.Count})");
    Console.WriteLine("═══════════════════════════════════════════");
    for (var i = 0; i < notes.Count; i++)
        Console.WriteLine($"\n--- Note {i + 1} ---\n{notes[i]}");
}

// ── Tool implementations ────────────────────────────────────────────────

async Task<string> SearchWeb(
    [Description("The search query string")] string query)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");
    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
        http.Timeout = TimeSpan.FromSeconds(15);

        // Use DuckDuckGo HTML search
        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        var html = await http.GetStringAsync(url);

        // Extract result snippets from the response
        var snippets = new List<string>();

        // Match result titles
        var titles = Regex.Matches(html,
            @"<a[^>]+class=""result__a""[^>]*>(.*?)</a>", RegexOptions.Singleline);

        // Match result snippets
        var bodies = Regex.Matches(html,
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline);

        var count = Math.Min(titles.Count, 8);
        for (var i = 0; i < count; i++)
        {
            var title = StripHtml(titles[i].Groups[1].Value).Trim();
            var body = i < bodies.Count
                ? StripHtml(bodies[i].Groups[1].Value).Trim()
                : "";
            if (!string.IsNullOrWhiteSpace(title))
                snippets.Add($"• {title}\n  {body}");
        }

        if (snippets.Count == 0)
            return $"No results found for \"{query}\".";

        return $"Search results for \"{query}\":\n\n" + string.Join("\n\n", snippets);
    }
    catch (Exception ex)
    {
        return $"Search failed for \"{query}\": {ex.Message}";
    }
}

void SaveNote(
    [Description("A short title for this note")] string title,
    [Description("The note content / findings")] string content)
{
    notes.Add($"**{title}**\n{content}");
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
}

string GetNotes()
{
    if (notes.Count == 0) return "No notes saved yet.";
    Console.WriteLine($"  📋 Reviewing {notes.Count} note(s)");
    return string.Join("\n\n---\n\n",
        notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
}

static string StripHtml(string html) =>
    Regex.Replace(html, @"<[^>]+>", "")
         .Replace("&amp;", "&")
         .Replace("&lt;", "<")
         .Replace("&gt;", ">")
         .Replace("&quot;", "\"")
         .Replace("&#x27;", "'")
         .Replace("&nbsp;", " ")
         .Trim();

